class LED:
    def __init__(self, pin):
        self.pin = pin
        self.status = False  # Av som standard

    def slaa_paa(self):
        self.status = True
        # digitalWrite(self.pin, HIGH)

    def slaa_av(self):
        self.status = False
        # digitalWrite(self.pin, LOW)

    def toggle(self):
        if self.status:
            self.slaa_av()
        else:
            self.slaa_paa()

led1 = LED(13)
led1.slaa_paa()
print(led1.status)  # True

class DCMotor:
    def __init__(self, pin):
        self.pin = pin
        self._hastighet = 0

    def sett_hastighet(self, n):
        if -100 <= n <= 100:
            self._hastighet = n
        else:
            raise ValueError("Hastighet må være mellom -100 og 100")

    def stopp(self):
        self._hastighet = 0

    def retning(self):
        if self._hastighet > 0:
            return "fremover"
        elif self._hastighet < 0:
            return "bakover"
        return "stoppet"

    @property
    def hastighet(self):
        return abs(self._hastighet)

class SmartEnhet:
    def __init__(self, enhet_id, rom):
        self.enhet_id = enhet_id
        self.rom = rom
        self.status = "av"

    def slaa_paa(self):
        self.status = "på"

    def slaa_av(self):
        self.status = "av"

class SmartLys(SmartEnhet):
    def __init__(self, enhet_id, rom):
        super().__init__(enhet_id, rom)
        self.lysstyrke = 0

    def dimme(self, nivå):
        self.lysstyrke = max(0, min(100, nivå))

class SmartTermostat(SmartEnhet):
    def __init__(self, enhet_id, rom):
        super().__init__(enhet_id, rom)
        self.maaltemperatur = 20
        self.naaverende_temp = 18

    def sett_temperatur(self, temp):
        self.maaltemperatur = temp

class SmartLaas(SmartEnhet):
    def __init__(self, enhet_id, rom):
        super().__init__(enhet_id, rom)
        self.låst = True

    def lås(self):
        self.låst = True

    def laas_opp(self, kode):
        if kode == "1234":
            self.låst = False
            return True
        return False

from datetime import datetime

class SensorLogg:
    def __init__(self, sensor_id, maks_malinger=1000):
        self.sensor_id = sensor_id
        self.maks_malinger = maks_malinger
        self._malinger = []  # [(tidspunkt, verdi), ...]

    def legg_til(self, verdi):
        tidspunkt = datetime.now()
        self._malinger.append((tidspunkt, verdi))
        if len(self._malinger) > self.maks_malinger:
            self._malinger.pop(0)

    def hent_siste(self, n=10):
        return self._malinger[-n:]

    def gjennomsnitt(self):
        if not self._malinger:
            return None
        verdier = [v for _, v in self._malinger]
        return sum(verdier) / len(verdier)

    def minimum(self):
        if not self._malinger:
            return None
        return min(v for _, v in self._malinger)

    def maksimum(self):
        if not self._malinger:
            return None
        return max(v for _, v in self._malinger)

    @property
    def antall_malinger(self):
        return len(self._malinger)

